    if kind == 'plate': roles += 'Image2: approved ficha C frame for dark iron/old-gold finish only; do not render its whole rectangular frame. '
    prompt = common + roles + request
    result = dict(code=code,revision='v01',kind=kind,target=size,content_state='DRAFT',runtime_admission=False,
                  status='PENDING',references=refs,prompt=prompt,**extra)
    jobs.append(result)
